import { defineConfig } from '@playwright/test';

// The service listens on PORT, 4310 unless overridden, and the tests talk to it
// through Playwright's request fixture. There is no browser anywhere in this
// project: every endpoint is JSON over HTTP and every acceptance test is an API
// test.
const port = Number(process.env.PORT ?? 4310);

// LOCKER_BASE_URL names a server something else already started and holds
// open, as tea-atdd-red-check does on an OS-assigned port. The webServer URL
// has to be that same server's, so `reuseExistingServer` finds it answering
// and Playwright starts nothing. Pointing the webServer at 4310 instead made
// Playwright start a second server on that fixed port for every spec file,
// which failed with "Process from config.webServer was not able to start"
// whenever another run on the host held 4310.
const baseURL = process.env.LOCKER_BASE_URL ?? `http://127.0.0.1:${port}`;

export default defineConfig({
  testDir: './tests',
  timeout: 15_000,
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: 'list',
  use: {
    baseURL,
  },
  webServer: {
    command: 'node src/server.js',
    url: `${baseURL}/health`,
    env: { PORT: String(port) },
    reuseExistingServer: !process.env.CI,
  },
});
# Story 4.2: Reserve a locker

Status: ready-for-dev

## Story

As a courier arriving at the quay,
I want to reserve a locker for the parcel I am carrying,
so that the locker is still free when I reach it and nobody else's parcel is put there in the meantime.

## Context

`quay-locker-service` already answers `GET /lockers` and `GET /lockers/{lockerId}` from the inventory in `src/lockers.js`. Nothing in the service knows about reservations yet: there is no reservation route, no reservation state, and the locker payload carries only `id`, `location` and `size`.

The service has no user interface. Every behavior below is an HTTP endpoint that speaks JSON, and the acceptance tests are API tests that run against the service started by `playwright.config.ts`.

## Acceptance Criteria

1. **AC-1: A free locker can be reserved.** `POST /lockers/{lockerId}/reservations` with a JSON body `{ "parcelId": "<string>", "durationMinutes": <integer> }` on a locker with no active reservation responds `201` with a JSON body carrying `reservationId` (a non-empty string), `lockerId` (the locker reserved), `parcelId` (the parcel given) and `expiresAt` (an ISO-8601 timestamp `durationMinutes` after the request).
2. **AC-2: A reserved locker cannot be reserved again.** `POST /lockers/{lockerId}/reservations` on a locker that already has an active reservation responds `409` with the JSON body `{ "error": "locker-reserved" }`, and the existing reservation is unchanged.
3. **AC-3: The duration is validated.** `POST /lockers/{lockerId}/reservations` responds `422` with the JSON body `{ "error": "invalid-duration" }` when `durationMinutes` is missing, is not an integer, is below 1, or is above 1440. No reservation is created.
4. **AC-4: A reservation can be released.** `DELETE /lockers/{lockerId}/reservations/{reservationId}` responds `204` with no body, and a subsequent `POST /lockers/{lockerId}/reservations` on the same locker responds `201` again.
5. **AC-5: The locker reports whether it is reserved.** `GET /lockers/{lockerId}` carries `"reserved": true` while the locker has an active reservation and `"reserved": false` otherwise, beside the existing `id`, `location` and `size` fields.

## Out of scope

- Expiry of a reservation whose `expiresAt` has passed. A later story sweeps expired reservations; until then a reservation is active until it is released.
- Listing reservations, or reserving several lockers in one request.
- Authentication. The service runs behind the quay gateway, which is the only caller.

## Dev Notes

- The inventory is in memory and resets when the process restarts, so a reservation store can live beside it in `src/`.
- `src/server.js` answers `404 { "error": "not-found" }` for every route it does not know, which is what the reservation routes return until they exist.
- Tests live under `tests/` and run with `npm test`, which starts the service through the `webServer` block of `playwright.config.ts`.

# quay-locker-service

The parcel locker inventory behind the quay pick-up points. Couriers drop parcels into lockers, customers collect them, and this service is what the quay gateway asks about lockers.

## Running it

```bash
npm start            # listens on http://127.0.0.1:4310, or PORT when set
npm test             # Playwright API tests under tests/, against a server it starts itself
```

There is no user interface and no browser. Every endpoint speaks JSON over HTTP, and every test is an API test written with Playwright's `request` fixture. `playwright.config.ts` starts the service on `PORT` before the tests run and points `baseURL` at it.

## Endpoints

| Method | Path                 | Response                                                          |
| ------ | -------------------- | ----------------------------------------------------------------- |
| GET    | `/health`            | `200 { "ok": true }`                                              |
| GET    | `/lockers`           | `200 [ { "id", "location", "size" }, ... ]`                       |
| GET    | `/lockers/{id}`      | `200 { "id", "location", "size" }` or `404 { "error": "locker-not-found" }` |
| any    | anything else        | `404 { "error": "not-found" }`                                    |

## Layout

```text
src/lockers.js     the inventory: three lockers, in memory
src/server.js      the HTTP server and its routes
docs/stories/      the stories the gateway team has scheduled for this service
tests/             acceptance tests
```
#!/usr/bin/env node
'use strict';

/**
 * quay-locker-service: the HTTP surface over the locker inventory.
 *
 * Two routes today:
 *
 *   GET /health          200 { "ok": true }
 *   GET /lockers         200 [ { id, location, size }, ... ]
 *   GET /lockers/{id}    200 { id, location, size }, or 404 when the id is unknown
 *
 * Every other path and method answers 404 with { "error": "not-found" }. The
 * body is JSON on every response.
 *
 * The server binds the loopback interface only, on PORT (default 4310).
 */

const http = require('node:http');

const { findLocker, listLockers } = require('./lockers');

const PORT = Number(process.env.PORT ?? 4310);
const HOST = '127.0.0.1';

function send(response, status, body) {
  const payload = body === undefined ? '' : JSON.stringify(body);
  response.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
  });
  response.end(payload);
}

function handle(request, response) {
  const url = new URL(request.url, `http://${HOST}:${PORT}`);
  const path = url.pathname;

  if (request.method === 'GET' && path === '/health') {
    send(response, 200, { ok: true });
    return;
  }
  if (request.method === 'GET' && path === '/lockers') {
    send(response, 200, listLockers());
    return;
  }
  const locker = /^\/lockers\/([^/]+)$/.exec(path);
  if (request.method === 'GET' && locker) {
    let id;
    try {
      id = decodeURIComponent(locker[1]);
    } catch {
      send(response, 400, { error: 'invalid-locker-id' });
      return;
    }
    const found = findLocker(id);
    if (found) send(response, 200, found);
    else send(response, 404, { error: 'locker-not-found' });
    return;
  }
  // Drain the body so a client that sent one is not left waiting on the pipe.
  request.resume();
  request.on('end', () => send(response, 404, { error: 'not-found' }));
}

const server = http.createServer(handle);
server.listen(PORT, HOST, () => {
  process.stdout.write(`quay-locker-service listening on http://${HOST}:${PORT}\n`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    // closeAllConnections is what makes this exit immediately rather than
    // waiting out a keep-alive socket. `server.close()` alone waits for every
    // open connection to end on its own, and a client holding one open (an
    // API-testing client's connection pool, reusing a socket between the
    // suite's requests) left this process alive well past Playwright's own
    // webServer teardown patience under one isolation backend, measured live.
    server.closeAllConnections();
    server.close(() => process.exit(0));
  });
}
'use strict';

/**
 * The locker inventory for the quay pick-up points.
 *
 * Three lockers, held in memory for the lifetime of the process. Each carries the
 * fields the lookup endpoint reports: an id, where it stands on the quay, and the
 * parcel size it takes.
 */
const LOCKERS = [
  { id: 'L-104', location: 'Pier 4, bay 1', size: 'medium' },
  { id: 'L-217', location: 'Pier 2, bay 7', size: 'large' },
  { id: 'L-330', location: 'Ferry hall, wall 3', size: 'small' },
];

const byId = new Map(LOCKERS.map((locker) => [locker.id, locker]));

/** Every locker, in inventory order. */
function listLockers() {
  return LOCKERS.map((locker) => ({ ...locker }));
}

/**
 * One locker by id, or null when the id is not in the inventory.
 *
 * @param {string} id
 * @returns {{id: string, location: string, size: string}|null}
 */
function findLocker(id) {
  const locker = byId.get(id);
  return locker ? { ...locker } : null;
}

module.exports = { listLockers, findLocker };
